import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash compatibility with mihomo, Clash Verge Rev, FlClash, Clash Nyanpasu, ClashMi and OpenClash","description":"Migrate mihomo YAML and subscriptions from Clash Verge Rev, FlClash, Clash Nyanpasu, ClashMi, OpenClash or ShellCrash to Clash for iPhone and iPad.","frontmatter":{"title":"Clash compatibility with mihomo, Clash Verge Rev, FlClash, Clash Nyanpasu, ClashMi and OpenClash","description":"Migrate mihomo YAML and subscriptions from Clash Verge Rev, FlClash, Clash Nyanpasu, ClashMi, OpenClash or ShellCrash to Clash for iPhone and iPad.","head":[["meta",{"name":"keywords","content":"mihomo iOS,Clash Verge Rev iOS,FlClash subscription,Clash Nyanpasu config,ClashMi config,OpenClash subscription,ShellCrash config"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Which mihomo client configurations work with Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Standard mihomo YAML configurations and subscriptions that return mihomo YAML can be imported directly, including configurations used by Clash Verge Rev, FlClash, Clash Nyanpasu, ClashMi, OpenClash and ShellCrash.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I use a Clash Verge Rev subscription in Clash for iOS?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes. Add the same mihomo subscription URL to Clash. When the panel offers multiple formats, change the subscription User-Agent to select Clash / mihomo output.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I use an OpenClash configuration in Clash for iOS?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Import the standard mihomo YAML directly and recreate the matching experience with Clash rules and iOS settings. OpenWrt plugin settings continue to be managed by the router.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/mihomo.md","filePath":"guide/compatibility/mihomo.md","lastUpdated":1785318168000}`),a={name:`guide/compatibility/mihomo.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="full-compatibility-with-mihomo-clients" tabindex="-1">Full compatibility with mihomo clients <a class="header-anchor" href="#full-compatibility-with-mihomo-clients" aria-label="Permalink to “Full compatibility with mihomo clients”">​</a></h1><p>A <strong>standard mihomo YAML configuration</strong>, or a subscription that returns mihomo YAML, can be imported directly into Clash. Nodes, policy groups, rules, providers and supported configuration fields continue to work, saving the step of recreating every node.</p><p>“Full compatibility” here means mihomo configuration and subscription compatibility. Interface preferences, system proxy, TUN and backup settings can be configured for your preferred workflow in Clash for iOS.</p><h2 id="popular-mihomo-clients" tabindex="-1">Popular mihomo clients <a class="header-anchor" href="#popular-mihomo-clients" aria-label="Permalink to “Popular mihomo clients”">​</a></h2><p>These are representative community projects:</p><table tabindex="0"><thead><tr><th>Client</th><th>Common platforms</th><th>Moving to Clash</th></tr></thead><tbody><tr><td><a href="https://github.com/clash-verge-rev/clash-verge-rev" target="_blank" rel="noreferrer">Clash Verge Rev</a></td><td>Windows, macOS, Linux</td><td>Import the mihomo YAML or add the same subscription</td></tr><tr><td><a href="https://github.com/chen08209/FlClash" target="_blank" rel="noreferrer">FlClash</a></td><td>Windows, macOS, Linux, Android</td><td>Import the mihomo YAML or add the same subscription</td></tr><tr><td><a href="https://github.com/libnyanpasu/clash-nyanpasu" target="_blank" rel="noreferrer">Clash Nyanpasu</a></td><td>Windows, macOS, Linux</td><td>Import the mihomo YAML or add the same subscription</td></tr><tr><td><a href="https://github.com/KaringX/clashmi" target="_blank" rel="noreferrer">ClashMi</a></td><td>iOS, macOS, Android, Windows, Linux</td><td>Import the mihomo YAML or add the same subscription</td></tr><tr><td><a href="https://github.com/vernesong/OpenClash" target="_blank" rel="noreferrer">OpenClash</a></td><td>OpenWrt</td><td>Import standard mihomo YAML; keep plugin settings managed by OpenWrt</td></tr><tr><td><a href="https://github.com/juewuy/ShellCrash" target="_blank" rel="noreferrer">ShellCrash</a></td><td>Routers and shell environments</td><td>Import standard mihomo YAML; keep installation and service settings in the original environment</td></tr></tbody></table><p>See the mihomo documentation for the broader <a href="https://wiki.metacubex.one/startup/client/client/" target="_blank" rel="noreferrer">third-party tools and clients list</a>.</p><h2 id="what-moves-directly" tabindex="-1">What moves directly? <a class="header-anchor" href="#what-moves-directly" aria-label="Permalink to “What moves directly?”">​</a></h2><ul><li>mihomo YAML configuration files;</li><li>subscription URLs that return mihomo YAML;</li><li>nodes and proxy providers;</li><li>policy groups and health checks;</li><li>routing rules and rule providers;</li><li>DNS and supported long-tail fields.</li></ul><h2 id="connect-platform-settings" tabindex="-1">Connect platform settings <a class="header-anchor" href="#connect-platform-settings" aria-label="Permalink to “Connect platform settings”">​</a></h2><p>Nodes, policy groups and rules move with mihomo YAML. Platform settings such as themes, window layouts, keyboard shortcuts, system proxy, TUN, launch at login, WebDAV backups and router plugins stay managed by their platform, with matching preferences available in Clash for iOS.</p><p>If the original client uses Merge, Mixin, overrides or scripts to generate its final configuration, export the generated standard mihomo YAML or use the original subscription URL.</p><h2 id="fastest-migration-path" tabindex="-1">Fastest migration path <a class="header-anchor" href="#fastest-migration-path" aria-label="Permalink to “Fastest migration path”">​</a></h2><ol><li>Find the active subscription URL in the original client.</li><li>Add that URL to Clash.</li><li>When the panel offers multiple formats, change the subscription User-Agent and select Clash / mihomo output.</li><li>Update the profile and confirm that groups, rules and nodes are present.</li><li>Test latency, choose a node and connect.</li></ol><h2 id="apple-platform-differences" tabindex="-1">Apple platform differences <a class="header-anchor" href="#apple-platform-differences" aria-label="Permalink to “Apple platform differences”">​</a></h2><p>iPhone and iPad use Apple&#39;s Packet Tunnel network-layer capabilities. Express desktop process- or app-routing goals with domain, IP and Rule Set policies; keep router interfaces, transparent proxy and firewall settings managed by the router.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};